with reviewed(id, patch) as (
  values
    (1771::bigint, jsonb_build_object(
      'queue_wait', 'This is a vast daytime cafe, not a nightlife door. Weekday mornings leave the most room to read; weekends and exhibition afternoons bring families, design crowds and a longer order line. Even when the counter is busy, the old factory floor offers far more breathing space than a typical Busan cafe.',
      'best_nights', 'Treat it as a long daytime date: start with hand-drip coffee and pastry, then drift into the used-book store, galleries, bamboo path and garden. A weekday gives the architecture room to breathe; a weekend works when a current exhibition matters more than quiet. It is not a queer event venue.',
      'crowd_mix', 'Local coffee regulars, couples, families, art students and domestic visitors make up most of the room, with international travellers drawn by the factory conversion. The atmosphere is mixed and design-led rather than explicitly LGBTQ+. Locals dominate, especially outside holiday weekends.',
      'dress_code', 'There is no dress code. Clean everyday layers, study clothes and camera-ready weekend outfits all fit beneath the steel frame. Wear shoes comfortable enough for the bookstore, galleries and garden; the pleasure here is wandering, not dressing for approval.',
      'staff_inclusivity', 'Reviews consistently praise the spacious, calm setting and careful coffee, without identifying an LGBTQ-specific hospitality policy. Queer visitors should read it as a polished mainstream cultural stop where mixed groups blend in easily, not as a community safe-space with trained queer staff.',
      'venue_classification', 'active_large_specialty_coffee_and_bakery_branch_inside_f1963_adaptive_reuse_cultural_complex_with_bookstore_galleries_gardens_local_daytime_crowd_and_mainstream_mixed_welcome',
      'identity_note', 'Terarosa Suyeong is the Terarosa branch inside F1963 at 20 Gurak-ro 123beon-gil. It is a mainstream cafe in a former wire factory, not an LGBTQ-specific venue.',
      'source_urls', to_jsonb(array['https://terarosa.com/','https://www.f1963.org/','https://www.visitbusan.net/index.busan?lang_cd=en&menuCd=DOM_000000301001001000&uc_seq=372','https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=225385','https://wanderlog.com/place/details/2412970','https://hongdiarytravel.com/terarosa-f1963-busan-specialty-coffee/']::text[]),
