        'crowd_mix', jsonb_build_object('status','mainstream_couple_cocktail_hotel_and_international_haeundae_visitor_mix_with_no_verified_lgbtq_core','source_urls',to_jsonb(array['https://www.tripadvisor.com/Attraction_Review-g297884-d12986888-Reviews-TBR_THE_BACK_ROOM-Busan.html','https://wanderlog.com/place/details/4945816','https://www.trip.com/restaurant/south-korea/busan/detail/tbr-the-back-room-62012617/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
