        'staff_inclusivity', jsonb_build_object('status','small_but_strong_bartender_performer_warmth_powerful_sound_and_committed_drag_consensus','source_urls',to_jsonb(array['https://wanderlog.com/place/details/6325068','https://qlist.app/venues/South-Korea/TightHall/YytSekRuQUhpUXRwWXIybzNoZjJRQQ']::text[]),'checked_at','2026-08-07T00:00:00Z')
