        'dress_code', jsonb_build_object('status','no_reported_code_with_casual_travel_and_neighbourhood_bar_style_while_drink_craft_supplies_polish','source_urls',to_jsonb(array['https://www.travelgay.com/venue/tool','https://qlist.app/venues/Busan/TOOL/anNOK25JQmVzZ1lMQ1pzOTJhUC9EUQ']::text[]),'checked_at','2026-08-07T00:00:00Z'),
