    (666::bigint, jsonb_build_object(
      'queue_wait', 'There is no current Cape Town queue. The chain closed in August 2024 after liquidation pressure, and the Green Point drag-dinner room is gone. Do not trust stale booking widgets or a 2026 event page carrying the old name; the former 40 Somerset Road venue should not receive reservations or directions.',
      'best_nights', 'The old formula peaked on drag-show and bingo evenings, when burgers, camp hosts and cabaret mattered more than a conventional dinner. That history is worth remembering, but it is not a current recommendation. Choose an active Cape Town drag calendar rather than planning around a resurrected listing.',
      'crowd_mix', 'Historically, queer diners mixed with birthday groups, bachelorettes, tourists and drag loyalists in a deliberately all-welcome room. The audience could feel more celebration-led than community-intimate. No present crowd exists after closure, so old ratings must remain clearly historical.',
      'dress_code', 'The former venue rewarded colour, sparkle and a willingness to join the joke, but never required costume. That is archival guidance only. There is no current Beefcakes door or valid dress policy in Cape Town, and any page implying otherwise risks sending dressed-up guests to a closed business.',
      'staff_inclusivity', 'Past praise centred on quick-witted drag hosts and playful service; criticism covered uneven food, ignored tables and pressure around paid extras. Closure reporting also documents financial strain. None of that proves a current team, so the record must stay hidden rather than borrow hospitality from its legacy.',
      'venue_classification', 'closed_august_2024_former_cape_town_queer_drag_dinner_cabaret_burger_bar_at_40_somerset_road_with_historic_mixed_celebration_crowd_camp_hosts_uneven_food_service_reviews_and_no_verified_reopening',
      'record_status', 'closed_former_drag_restaurant_hide_from_search_maps_sitemap_city_counts_recommendations_and_current_venue_intelligence_scoring',
      'identity_note', 'Beefcakes Cape Town closed with the wider South African chain in August 2024. Current closed-place reports and 2026 local discussion confirm no reopening at 40 Somerset Road; stale event and booking pages are not evidence of active trade.',
      'source_urls', to_jsonb(array['https://www.mambaonline.com/2024/08/19/end-of-an-era-beefcakes-shuts-down/','https://capetown.gaycities.com/restaurants/309325-beefcakes','https://restaurantguru.com/Beefcakes-Cape-Town','https://www.reddit.com/r/capetown/comments/1qeb3z7/drag_shows/','https://www.eatout.co.za/venue/beefcakesgreenpoint/']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','confirmed_no_current_queue_after_august_2024_chain_closure_and_warning_against_stale_booking_or_event_pages','source_urls',to_jsonb(array['https://www.mambaonline.com/2024/08/19/end-of-an-era-beefcakes-shuts-down/','https://capetown.gaycities.com/restaurants/309325-beefcakes','https://restaurantguru.com/Beefcakes-Cape-Town']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'best_nights', jsonb_build_object('status','historic_drag_and_bingo_peak_only_with_no_current_programme_or_honest_visit_recommendation','source_urls',to_jsonb(array['https://www.mambaonline.com/2024/08/19/end-of-an-era-beefcakes-shuts-down/','https://www.eatout.co.za/venue/beefcakesgreenpoint/','https://www.reddit.com/r/capetown/comments/1qeb3z7/drag_shows/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','historic_queer_diner_birthday_bachelorette_tourist_and_drag_fan_mix_only_with_no_current_crowd','source_urls',to_jsonb(array['https://www.mambaonline.com/2024/08/19/end-of-an-era-beefcakes-shuts-down/','https://capetown.gaycities.com/restaurants/309325-beefcakes','https://www.eatout.co.za/venue/beefcakesgreenpoint/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','historic_colour_and_camp_without_required_costume_but_no_current_door_or_valid_policy','source_urls',to_jsonb(array['https://capetown.gaycities.com/restaurants/309325-beefcakes','https://www.eatout.co.za/venue/beefcakesgreenpoint/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
