    (667::bigint, jsonb_build_object(
      'queue_wait', 'The new Cobern Street bar is quiet early and can feel almost private on a weekday or Sunday. Friday-Saturday events build after 21:00; recent listings offer free entry before then and a modest cover later. It is a cosy dance room, not a giant club, so arriving early matters more than winning a selective door.',
      'best_nights', 'Friday and Saturday bring DJs and the most reliable dancing; karaoke, live music and Pride dates add character beyond a playlist. Happy hour is useful for meeting people before the floor wakes up. Sunday is consistently described as very quiet, better for a drink than a destination night.',
      'crowd_mix', 'Gay men remain the visible core, joined by broader LGBTQ+ regulars, visitors and friends. The relocated room feels local and conversational before the weekend dance crowd arrives. It is less tourist-slick than old De Waterkant mythology suggests, with the energy changing sharply by hour and event.',
      'dress_code', 'Ordinary nights are relaxed: fitted casualwear, trainers and a going-out shirt work. Ticketed themes can be strict—its New Year''s event required full disco glamour and refused low effort—so read the actual listing. Never assume one costume brief is the permanent policy.',
      'staff_inclusivity', 'Recent guests split hard: some praise a welcoming manager, strong air-conditioning, quick service and a safe-feeling room; others allege arbitrary pricing, automatic tips and poor incident response. Check the amount before tapping, keep the receipt and raise discrepancies immediately.',
      'venue_classification', 'active_relocated_gay_and_lgbtq_bar_club_at_cobern_street_with_small_dancefloor_weekend_djs_karaoke_live_music_pride_events_early_quiet_local_social_energy_theme_specific_dress_and_material_billing_service_dispute_reports',
      'identity_note', 'Crew Bar is active at 10–12 Cobern Street, De Waterkant, not its former 30 Napier Street address. A May 2026 event and March 2026 reviews confirm current trade; older closed markers refer to the previous listing/location.',
      'source_urls', to_jsonb(array['https://infogaytion.com/south-africa/cape-town/events/sanctuary-at-crew-bar-cape-town','https://wanderlog.com/place/details/9264147/crew-bar','https://www.gayout.com/africa/south-africa/cape-town/bars/crew-bar-139','https://qlist.app/venues/Cape-Town/Crew-Bar/TWsyMy9jajdkY1JPa2NGeFRHWlBlZw','https://www.howler.co.za/events/the-nye-great-gatsby-gala-e7a4','https://capetowndata.com/en/products/blogpost/813/']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','new_cobern_room_quiet_early_and_sunday_with_post_2100_weekend_event_build_free_early_then_modest_cover','source_urls',to_jsonb(array['https://infogaytion.com/south-africa/cape-town/events/sanctuary-at-crew-bar-cape-town','https://wanderlog.com/place/details/9264147/crew-bar','https://www.gayout.com/africa/south-africa/cape-town/bars/crew-bar-139']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'best_nights', jsonb_build_object('status','friday_saturday_dj_dancing_plus_karaoke_live_music_and_pride_programming_with_consistently_quiet_sunday','source_urls',to_jsonb(array['https://infogaytion.com/south-africa/cape-town/events/sanctuary-at-crew-bar-cape-town','https://wanderlog.com/place/details/9264147/crew-bar','https://capetowndata.com/en/products/blogpost/813/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','gay_male_core_broader_lgbtq_regular_visitor_and_friend_mix_with_local_early_conversation_and_weekend_dance_shift','source_urls',to_jsonb(array['https://qlist.app/venues/Cape-Town/Crew-Bar/TWsyMy9jajdkY1JPa2NGeFRHWlBlZw','https://wanderlog.com/place/details/9264147/crew-bar','https://www.gayout.com/africa/south-africa/cape-town/bars/crew-bar-139']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','relaxed_ordinary_night_style_with_strict_event_specific_nye_disco_glamour_code_not_generalized','source_urls',to_jsonb(array['https://www.howler.co.za/events/the-nye-great-gatsby-gala-e7a4','https://wanderlog.com/place/details/9264147/crew-bar']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','current_manager_service_aircon_and_safe_room_praise_balanced_against_billing_tip_pricing_and_incident_response_complaints','source_urls',to_jsonb(array['https://wanderlog.com/place/details/9264147/crew-bar','https://www.gayout.com/africa/south-africa/cape-town/bars/crew-bar-139','https://www.tripadvisor.com/Attraction_Review-g312659-d10435046-Reviews-Crew_Bar-Cape_Town_Central_Western_Cape.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
