    (1303::bigint, jsonb_build_object(
      'queue_wait', 'There is no nightlife queue: this is a seven-room heritage guesthouse with booked check-in. Send arrival details in advance because reception is handled through the wider guesthouse operation, and the check-in point can differ from the front door. Peak summer and Pride weeks are an availability problem, not a line.',
      'best_nights', 'Stay here when walking home through De Waterkant matters more than a resort scene. A warm evening in the courtyard or by the small pool suits a reset before dinner; mornings are quiet and continental. Pride season places the queer district outside your door, while ordinary weeks feel residential and discreet.',
      'crowd_mix', 'International couples, solo city-break guests and LGBTQ+ travellers choose it for the historic gay village and central access. It is not men-only and current booking feedback is broadly mixed-demographic. Tourists dominate inside; local queer life appears in the surrounding bars, cafes and streets.',
      'dress_code', 'No code beyond guesthouse common-space manners. Pool layers, linen, sightseeing clothes and a sharper dinner look all move easily through the compact house. Pack for steep Cape Town streets and changeable weather; heritage charm also means rooms and bathroom layouts vary, so read your room category.',
      'staff_inclusivity', 'Verified guests repeatedly call the team friendly, available and generous with local tips, with especially strong scores for staff, cleanliness and location. Specialist approval supports LGBTQ+ welcome. A few guests find breakfast basic or room layouts intimate, but warmth and feeling at home dominate.',
      'venue_classification', 'active_small_cape_georgian_heritage_guesthouse_at_35_loader_street_operated_by_cape_finest_with_pool_courtyard_central_gay_village_access_international_mixed_guests_verified_high_staff_location_and_cleanliness_scores',
      'identity_note', 'The current Cape Finest – De Waterkant House is at 35 Loader Street, not the stored 137 Waterkant Street. The official house site and current booking platforms agree on Loader Street and Cape Finest operation.',
      'source_urls', to_jsonb(array['https://www.dewaterkanthouse.co.za/','https://www.capefinest.co.za/','https://www.booking.com/reviews/za/hotel/dewaterkanthouse-cape-town1.html','https://www.booking.com/hotel/za/dewaterkanthouse-cape-town1.en-gb.html','https://www.expedia.com/Cape-Town-Hotels-De-Waterkant-House.h101986973.Hotel-Information','https://www.travelgay.com/hotels/de-waterkant-house-cape-town']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','booked_seven_room_guesthouse_with_advance_arrival_coordination_and_separate_checkin_point_not_nightlife_queue','source_urls',to_jsonb(array['https://www.dewaterkanthouse.co.za/','https://www.booking.com/hotel/za/dewaterkanthouse-cape-town1.en-gb.html','https://www.expedia.com/Cape-Town-Hotels-De-Waterkant-House.h101986973.Hotel-Information']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'best_nights', jsonb_build_object('status','gay_village_walkability_courtyard_pool_evening_and_quiet_morning_stay_with_pride_season_location_value','source_urls',to_jsonb(array['https://www.dewaterkanthouse.co.za/','https://www.travelgay.com/hotels/de-waterkant-house-cape-town','https://www.booking.com/reviews/za/hotel/dewaterkanthouse-cape-town1.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','international_couple_solo_city_break_and_lgbtq_traveller_mix_not_men_only_with_tourist_inside_local_queer_district_outside','source_urls',to_jsonb(array['https://www.booking.com/reviews/za/hotel/dewaterkanthouse-cape-town1.html','https://www.travelgay.com/hotels/de-waterkant-house-cape-town','https://www.expedia.com/Cape-Town-Hotels-De-Waterkant-House.h101986973.Hotel-Information']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','no_code_with_pool_sightseeing_and_dinner_style_plus_heritage_room_layout_variation','source_urls',to_jsonb(array['https://www.dewaterkanthouse.co.za/','https://www.booking.com/hotel/za/dewaterkanthouse-cape-town1.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','verified_high_staff_cleanliness_location_and_local_tip_praise_plus_specialist_lgbtq_approval_balanced_by_basic_breakfast_and_layout_notes','source_urls',to_jsonb(array['https://www.booking.com/reviews/za/hotel/dewaterkanthouse-cape-town1.html','https://www.expedia.com/Cape-Town-Hotels-De-Waterkant-House.h101986973.Hotel-Information','https://www.travelgay.com/hotels/de-waterkant-house-cape-town']::text[]),'checked_at','2026-08-07T00:00:00Z')
